using UnityEngine;
using System.Collections.Generic;

public class DragDropManager : MonoBehaviour
{
    public static DragDropManager Instance { get; private set; }

    [Header("Debug")]
    public bool enableDebugLogs = true;

    private CharacterDragSource currentDragSource = null;
    private List<CharacterDragSource> allDragSources = new List<CharacterDragSource>();

    void Awake()
    {
        if (Instance == null)
        {
            Instance = this;
            DontDestroyOnLoad(gameObject);
        }
        else
        {
            Destroy(gameObject);
        }
    }

    void Start()
    {
        RefreshDragSources();
    }

    public void RefreshDragSources()
    {
        allDragSources.Clear();
        allDragSources.AddRange(FindObjectsOfType<CharacterDragSource>());

        if (enableDebugLogs)
            Debug.Log($"[DragDropManager] Found {allDragSources.Count} drag sources");
    }

    public bool CanStartDrag(CharacterDragSource source)
    {
        if (currentDragSource != null && currentDragSource != source)
        {
            if (enableDebugLogs)
                Debug.Log($"[DragDropManager] Cannot start drag - another source is active: {currentDragSource.name}");
            return false;
        }

        return true;
    }

    public void StartDrag(CharacterDragSource source)
    {
        if (currentDragSource != null && currentDragSource != source)
        {
            // Force end the current drag
            currentDragSource.ForceEndDrag();
        }

        currentDragSource = source;

        if (enableDebugLogs)
            Debug.Log($"[DragDropManager] Started drag for: {source.name}");
    }

    public void EndDrag(CharacterDragSource source)
    {
        if (currentDragSource == source)
        {
            currentDragSource = null;

            if (enableDebugLogs)
                Debug.Log($"[DragDropManager] Ended drag for: {source.name}");
        }
        else if (enableDebugLogs)
        {
            Debug.LogWarning($"[DragDropManager] Attempted to end drag for {source.name} but current is {(currentDragSource != null ? currentDragSource.name : "null")}");
        }
    }

    public void ForceEndAllDrags()
    {
        if (currentDragSource != null)
        {
            currentDragSource.ForceEndDrag();
            currentDragSource = null;
        }

        // Also reset all drag sources as backup
        foreach (CharacterDragSource source in allDragSources)
        {
            if (source != null && source.isDragging)
            {
                source.ForceEndDrag();
            }
        }

        if (enableDebugLogs)
            Debug.Log("[DragDropManager] Force ended all drags");
    }

    public bool IsDragging()
    {
        return currentDragSource != null;
    }

    public CharacterDragSource GetCurrentDragSource()
    {
        return currentDragSource;
    }

    void Update()
    {
        // Safety check - if current drag source is null but we think something is dragging
        if (currentDragSource != null && !currentDragSource.isDragging)
        {
            if (enableDebugLogs)
                Debug.LogWarning("[DragDropManager] Current drag source is not dragging - clearing");
            currentDragSource = null;
        }

        // Check for mouse release globally
        var mouse = UnityEngine.InputSystem.Mouse.current;
        if (mouse != null && !mouse.leftButton.isPressed && currentDragSource != null)
        {
            if (enableDebugLogs)
                Debug.Log("[DragDropManager] Global mouse release detected - ending drag");
            ForceEndAllDrags();
        }
    }
}

